import docx
from docx.shared import Inches, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from kmutnb_thai_helpers import (
    add_p, add_h1, add_h2, add_h3, add_h4,
    FONT_SIZE_BODY, FONT_SIZE_H1, FONT_SIZE_H2, FONT_SIZE_H3
)

def build_chapter_1(doc):
    add_h1(doc, "บทที่ 1", "บทนำ")
    
    add_p(doc, "บทนี้จะกล่าวถึงความเป็นมาและความสำคัญของปัญหาในการตรวจพิจารณาสำนวนการสอบสวนคดีอาญาของพนักงานอัยการ วัตถุประสงค์ของการจัดทำโครงงาน ขอบเขตของโครงงานที่แบ่งแยกระหว่างระบบส่วนหลังและระบบส่วนหน้าอย่างชัดเจน ตลอดจนประโยชน์ที่คาดว่าจะได้รับจากการพัฒนาระบบ CyberCase Intelligence Framework ขึ้นมาใช้งาน")
    
    add_h2(doc, "1.1 ความเป็นมาและความสำคัญของโครงงาน")
    add_p(doc, "ในระบบกระบวนการยุติธรรมทางอาญาของประเทศไทย พนักงานอัยการมีบทบาทหน้าที่ตามประมวลกฎหมายวิธีพิจารณาความอาญา ในการตรวจพิจารณาสำนวนการสอบสวนที่พนักงานสอบสวน (เจ้าหน้าที่ตำรวจ) ส่งมอบมาให้เพื่อพิจารณามีคำสั่งทางคดี ไม่ว่าจะเป็นคำสั่งฟ้อง สั่งไม่ฟ้อง หรือสั่งให้พนักงานสอบสวนทำการสอบสวนเพิ่มเติม สำนวนการสอบสวนแต่ละคดีประกอบไปด้วยเอกสารทางกฎหมายและพยานหลักฐานจำนวนมาก ได้แก่ หนังสือนำส่งสำนวน รายงานการสอบสวนของพนักงานสอบสวน บันทึกคำให้การของผู้กล่าวหา ผู้ต้องหา และพยานบุคคล บันทึกการตรวจสถานที่เกิดเหตุ บัญชีของกลาง บันทึกการแจ้งข้อกล่าวหา ตลอดจนพยานหลักฐานทางนิติวิทยาศาสตร์และพยานหลักฐานทางอิเล็กทรอนิกส์")
    add_p(doc, "จากการศึกษาและสำรวจตัวอย่างสำนวนการสอบสวนจริง เช่น สำนวนการสอบสวนในคดีฉ้อโกงและคดีความผิดเกี่ยวกับทรัพย์ (อาทิ รายงานการสอบสวนเลขที่ 902-2563, 632-2564 และ 903-2564) พบว่าในปัจจุบันพยานหลักฐานทางดิจิทัลได้เข้ามามีบทบาทในคดีอาญาทั่วไปอย่างแพร่หลาย พนักงานสอบสวนมักรวบรวมพยานเอกสารที่ได้จากระบบอิเล็กทรอนิกส์ เช่น ภาพถ่ายหน้าจอการสนทนาผ่านแอปพลิเคชัน LINE บันทึกประวัติการโทรศัพท์ สลิปหลักฐานการโอนเงินผ่านระบบโมบายแบงก์กิ้ง บัญชีเงินฝากธนาคาร และภาพถ่ายกล้องวงจรปิด อย่างไรก็ตาม พยานหลักฐานดิจิทัลเหล่านี้ส่วนใหญ่เป็นเพียง 'วัตถุพยานในคดีอาญาทั่วไป' (Ordinary Electronic Evidence) มิได้เกิดจากการกระทำความผิดที่มีลักษณะเป็นการเจาะระบบเครือข่าย หรือการใช้มัลแวร์ในรูปแบบภัยคุกคามทางไซเบอร์ขั้นสูง (Cyber-Adversarial Behaviors)")
    add_p(doc, "ปัญหาสำคัญในการปฏิบัติงานของพนักงานอัยการ คือ:")
    add_p(doc, "1. ภาระงานและเวลาในการตรวจเอกสาร (High Cognitive Overhead): พนักงานอัยการต้องใช้เวลาอย่างมากในการอ่านเอกสารที่มีความยาวหลายสิบหรือหลายร้อยหน้า เพื่อแยกแยะบุคคลที่เกี่ยวข้อง (ใครเป็นผู้เสียหาย ใครเป็นผู้ต้องหา ใครเป็นพยาน) สกัดลำดับเหตุการณ์ตามวันเวลาจริง (Chronology) และจับคู่ข้อกล่าวหากับพยานหลักฐานที่สนับสนุน", first_indent=0.75)
    add_p(doc, "2. ความเสี่ยงจากการสับสนประเภทข้อมูล: ในรายงานการสอบสวน มักมีทั้ง 'ข้อเท็จจริงที่มีหลักฐานยืนยัน' 'คำซักถามของพยานที่อาจขัดแย้งกัน' และ 'ความเห็นทางคดีของพนักงานสอบสวน' หากผู้อ่านไม่มีความเชี่ยวชาญ อาจเข้าใจผิดว่าความเห็นของพนักงานสอบสวนเป็นข้อเท็จจริงที่ยุติแล้ว", first_indent=0.75)
    add_p(doc, "3. ข้อจำกัดของเทคโนโลยีปัญญาประดิษฐ์และโมเดลภาษาขนาดใหญ่ (LLMs): แม้ว่าในปัจจุบันจะมีการนำโมเดลภาษาขนาดใหญ่มาช่วยสรุปข้อความ แต่โมเดลทั่วไปมักประสบปัญหาการเกิดภาพหลอน (Hallucination) การสร้างข้อความสรุปที่ฟังดูน่าเชื่อถือแต่ไม่มีพยานหลักฐานจริงในสำนวนรองรับ การอ้างอิงหน้าที่ผิดพลาด และที่ร้ายแรงที่สุดคือการนำเอาข้อมูลภายนอก เช่น ฐานข้อมูลเทคนิคภัยคุกคาม MITRE ATT&CK มาสรุปปะปนเสมือนเป็นพฤติการณ์ที่เกิดขึ้นจริงในคดี ทั้งที่ในสำนวนเป็นเพียงการสนทนาทาง LINE หรือการโอนเงินธรรมดา", first_indent=0.75)
    add_p(doc, "ด้วยเหตุนี้ ผู้จัดทำจึงมีแนวคิดในการวิจัยและพัฒนาระบบ CyberCase Intelligence Framework ซึ่งเป็นระบบเว็บแอปพลิเคชันที่มุ่งเน้นการสนับสนุนการตรวจพิจารณาสำนวนคดีอาญาของพนักงานอัยการ โดยมีหัวใจสำคัญอยู่ที่ 'การรักษาความถูกต้องของพยานหลักฐาน' (Evidence-Grounded System) โดยระบบจะช่วยสกัดโครงสร้าง 5W1H จัดลำดับเหตุการณ์ ระบุสถานะเชิงประจักษ์ของข้ออ้าง ตรวจสอบข้อความอ้างอิงตรงจากเอกสารต้นฉบับ ชี้จุดช่องว่างความไม่สมบูรณ์ของสำนวน และเชื่อมโยงความรู้ทางเทคนิคภายนอกอย่างมีเงื่อนไขและปลอดภัย")

    add_h2(doc, "1.2 วัตถุประสงค์ของโครงงาน")
    add_p(doc, "โครงงานปริญญานิพนธ์นี้มีวัตถุประสงค์หลักในการวิจัยและพัฒนา 4 ประการ ดังนี้:")
    add_p(doc, "1.2.1 เพื่อพัฒนาระบบส่วนหลัง (Backend Application) สำหรับประมวลผลและวิเคราะห์สำนวนคดีอาญา โดยสามารถสกัดข้อมูล 5W1H (Who, What, Where, When, Why, How) ลำดับเหตุการณ์ตามเวลา และจำแนกข้ออ้างออกเป็นสถานะเชิงประจักษ์ (Reported, Inference, Unresolved, Disputed) เพื่อให้พนักงานอัยการเข้าใจภาพรวมคดีได้อย่างรวดเร็วและถูกต้อง", first_indent=0.75)
    add_p(doc, "1.2.2 เพื่อพัฒนากลไกการตรวจสอบความถูกต้องของพยานหลักฐานต้นทาง (Source Traceability & Quote Validation) ที่สามารถยืนยันข้อความอ้างอิงตรง (Verbatim Quote) และพิกัดหน้าเอกสารได้อย่างแม่นยำ พร้อมพัฒนาระบบถามเพื่อความกระจ่างแบบมีสถานะ (Stateful Clarification Policy) ที่จำกัดการถามไม่ให้วนซ้ำในประเด็นเดิม", first_indent=0.75)
    add_p(doc, "1.2.3 เพื่อเชื่อมต่อและบูรณาการบริการสืบค้นองค์ความรู้ทางเทคนิคภายนอก (Downstream RAG Service) ผ่านส่วนต่อประสานที่กำหนดขอบเขตความเชื่อถืออย่างเคร่งครัด (Evidence Trust Boundary) โดยมีตัวคัดกรองความเกี่ยวข้องทางไซเบอร์ (Applicability Gate) ป้องกันไม่ให้องค์ความรู้ภายนอกปะปนกับข้อเท็จจริงในคดี", first_indent=0.75)
    add_p(doc, "1.2.4 เพื่อพัฒนาเว็บแอปพลิเคชันส่วนหน้า (Frontend Web Workspace) ที่ตอบสนองต่อการทำงานของพนักงานอัยการในการเตรียมเอกสาร ตรวจสอบภาพรวม ตรวจสอบหลักฐานในเอกสารต้นฉบับ และสร้างรายงานสรุปสำนวนคดีอัตโนมัติในรูปแบบ PDF ที่มีโครงสร้างแน่นอน (Deterministic Report Generation) โดยไม่เกิดปัญหาภาพหลอนซ้ำซ้อน", first_indent=0.75)

    add_h2(doc, "1.3 ขอบเขตของโครงงาน")
    add_p(doc, "เพื่อให้การดำเนินงานโครงงานเป็นไปอย่างมีประสิทธิภาพและชัดเจน ผู้จัดทำได้กำหนดขอบเขตการทำงานโดยเน้นความรับผิดชอบในส่วน 'ระบบส่วนหลัง (Backend API) และระบบส่วนหน้า (Frontend Web Workspace)' โดยกำหนดให้ระบบสืบค้นและวิเคราะห์กราฟความรู้ภายนอก (rag_service) เป็นบริการปลายน้ำของผู้ร่วมโครงงาน โดยมีรายละเอียดขอบเขตดังนี้:")
    
    add_h3(doc, "1.3.1 ขอบเขตระบบส่วนหลัง (Backend Application)")
    add_p(doc, "1.3.1.1 พัฒนาด้วยภาษา Python โดยใช้เฟรมเวิร์ก FastAPI ในรูปแบบ Asynchronous API ทั้งหมด", first_indent=0.75)
    add_p(doc, "1.3.1.2 ใช้ฐานข้อมูลเชิงสัมพันธ์ PostgreSQL ร่วมกับ SQLAlchemy (Async Engine) ในการจัดเก็บข้อมูล Workspace, Messages, Background Runs, Retrieval Contexts และ Reports", first_indent=0.75)
    add_p(doc, "1.3.1.3 มีระบบสกัดข้อความจากเอกสารสำนวนคดี (Document Ingestion Preview) รองรับไฟล์ PDF และ DOCX พร้อมแสดงผลตัวอย่างข้อความให้ผู้ใช้ตรวจทานก่อนยืนยัน", first_indent=0.75)
    add_p(doc, "1.3.1.4 มีตัวคัดกรองความเกี่ยวข้องทางไซเบอร์ (Pre-Retrieval Applicability Gate) ทำหน้าที่จำแนกว่าพยานหลักฐานในสำนวนมีพฤติการณ์โจมตีทางไซเบอร์จริงหรือไม่ หากไม่มีจะข้ามการเรียก RAG ภายนอกทันที (SKIP)", first_indent=0.75)
    add_p(doc, "1.3.1.5 มีเอ็นจินวิเคราะห์สำนวนคดีหลัก (Main Case Analysis Engine) ส่งคำขอและตรวจสอบโครงสร้างคำตอบของโมเดลตามสัญญา Pydantic v3 สกัดภาพรวม 5W1H ลำดับเหตุการณ์ และรายการข้ออ้างเชิงประจักษ์", first_indent=0.75)
    add_p(doc, "1.3.1.6 มีระบบตรวจสอบความถูกต้องของข้อความอ้างอิงตรง (Verbatim Citation Validator) ตรวจสอบว่าข้อความที่โมเดลอ้างอิงมีอยู่จริงในเอกสารต้นทางแบบตัวอักษรต่อตัวอักษร หากไม่ตรงจะตัดทิ้งทันที และปรับลดระดับพิกัดหน้าเอกสารอย่างปลอดภัยหากตรวจพบความคลุมเครือ", first_indent=0.75)
    add_p(doc, "1.3.1.7 มีระบบนโยบายถามความกระจ่างแบบมีสถานะ (Stateful Clarification Policy) ตรวจหาช่องว่างพยานหลักฐาน (Evidentiary Gaps) จัดลำดับความสำคัญ และบันทึกประเด็นที่เคยถามแล้วเพื่อตัดลูปถาวร (Topic Exhaustion)", first_indent=0.75)
    add_p(doc, "1.3.1.8 มีระบบจัดการ Worker แบบเช่าเวลา (Transactional Leased Worker) พร้อมกลไก Heartbeat Renewal และการกู้คืนงานที่ขัดข้อง (Run Recovery & Idempotent Retry)", first_indent=0.75)
    add_p(doc, "1.3.1.9 มีระบบสร้างรายงานสรุปสำนวนคดีอัตโนมัติด้วย ReportLab โดยใช้ Template-First Deterministic Assembly จาก Snapshot ที่บันทึกไว้โดยไม่เรียกใช้โมเดลภาษาซ้ำซ้อน", first_indent=0.75)

    add_h3(doc, "1.3.2 ขอบเขตระบบส่วนหน้า (Frontend Web Application)")
    add_p(doc, "1.3.2.1 พัฒนาด้วย Next.js 16 (App Router), React 19, TypeScript และตกแต่งด้วย Tailwind CSS 4", first_indent=0.75)
    add_p(doc, "1.3.2.2 ใช้ TanStack Query ในการจัดการสถานะข้อมูลฝั่งเซิร์ฟเวอร์แบบรวมศูนย์ (Single Polling Loop) และแยกสถานะแบบร่าง (Draft State) ไม่ให้ถูกเขียนทับขณะระบบกำลังประมวลผล", first_indent=0.75)
    add_p(doc, "1.3.2.3 หน้าจอเตรียมเอกสารสำนวนคดี (Case Preparation Workspace): อัปโหลดเอกสาร ดูตัวอย่างข้อความสกัด ตรวจสอบค่าความเชื่อมั่น OCR และกดยืนยันเพื่อเริ่มวิเคราะห์", first_indent=0.75)
    add_p(doc, "1.3.2.4 หน้าจอภาพรวมสำนวนคดี (Case Overview Workspace): แสดงสรุป 5W1H ไทม์ไลน์เหตุการณ์ การ์ดข้ออ้างเชิงประจักษ์จำแนกตามสีและสถานะความไม่แน่นอน พร้อมการ์ดแจ้งเตือนประเด็นข้อสงสัย", first_indent=0.75)
    add_p(doc, "1.3.2.5 หน้าจอลิ้นชักตรวจสอบหลักฐานต้นฉบับ (Source Inspection Drawer): เมื่อคลิกที่ชิปอ้างอิง ระบบจะเปิดลิ้นชักแสดงเอกสารสำนวนคดีและทำไฮไลต์ข้อความอ้างอิงตรงทันที", first_indent=0.75)
    add_p(doc, "1.3.2.6 หน้าจอรายงานสรุปสำนวนคดี (Interactive Report View): แสดงตัวอย่างรายงานและดาวน์โหลดไฟล์เอกสาร PDF มาตรฐาน", first_indent=0.75)

    add_h3(doc, "1.3.3 ขอบเขตการเชื่อมต่อบริการภายนอก (Downstream RAG Boundary)")
    add_p(doc, "1.3.3.1 เชื่อมต่อกับบริการ GraphRAG ของผู้ร่วมโครงงานผ่าน REST API endpoint ที่กำหนดไว้", first_indent=0.75)
    add_p(doc, "1.3.3.2 ระบบส่วนหลังทำหน้าที่ส่งคำค้นที่สกัดพฤติกรรมทางเทคนิค ตรวจสอบโครงสร้างข้อมูล STIX 2.1 / MITRE ATT&CK ที่ตอบกลับมา และบันทึกลงตาราง rag_contexts", first_indent=0.75)
    add_p(doc, "1.3.3.3 โครงงานนี้ไม่ครอบคลุมการออกแบบหรือพัฒนากลไกการทำ Graph Expansion, Vector Indexing หรือ Agentic Loop ภายในระบบบริการภายนอกดังกล่าว", first_indent=0.75)

    add_h3(doc, "1.3.4 ขอบเขตข้อมูลและการใช้งาน")
    add_p(doc, "1.3.4.1 รองรับเอกสารสำนวนคดีภาษาไทยในรูปแบบข้อความ (Text), PDF และ DOCX", first_indent=0.75)
    add_p(doc, "1.3.4.2 ระบบเป็นต้นแบบสำหรับผู้ใช้งานเดี่ยว (Single-User Prototype) ยังไม่ครอบคลุมระบบการยืนยันตัวตนระดับองค์กร (Authentication) หรือระบบกำหนดสิทธิ์หลายระดับ (RBAC)", first_indent=0.75)
    add_p(doc, "1.3.4.3 ระบบปิดการทำงานของฟังก์ชันรู้จำลายมือเขียน (Handwriting Recognition: HTR) เป็นการชั่วคราว เนื่องจากโมเดลเชิงพาณิชย์ยังมีความแม่นยำต่ำต่อลายมือภาษาไทย", first_indent=0.75)

    add_h2(doc, "1.4 ประโยชน์ที่คาดว่าจะได้รับ")
    add_p(doc, "1.4.1 ช่วยลดระยะเวลาและภาระในการตรวจพิจารณาสำนวนคดีของพนักงานอัยการ โดยระบบสามารถจัดระเบียบข้อมูลบุคคล เหตุการณ์ และข้อกล่าวหาที่ซับซ้อนให้ออกมาเป็นโครงสร้าง 5W1H ที่เข้าใจได้ง่ายและรวดเร็ว")
    add_p(doc, "1.4.2 เพิ่มความถูกต้องแม่นยำและโปร่งใสในการตรวจสอบพยานหลักฐาน โดยพนักงานอัยการสามารถตรวจสอบย้อนกลับไปยังข้อความจริงในสำนวนคดีได้ทันทีผ่านระบบไฮไลต์ข้อความตรง ขจัดปัญหาการหลงเชื่อข้อความสรุปที่คลาดเคลื่อน")
    add_p(doc, "1.4.3 ช่วยชี้จุดบกพร่องหรือช่องว่างของพยานหลักฐานในสำนวนคดีได้อย่างเป็นรูปธรรม ช่วยให้พนักงานอัยการสามารถสั่งสอบสวนเพิ่มเติมได้อย่างตรงจุด และไม่เกิดการถามซ้ำซากในประเด็นเดิม")
    add_p(doc, "1.4.4 ได้เอกสารรายงานสรุปสำนวนคดี (PDF) ที่มีมาตรฐานแน่นอน มีความน่าเชื่อถือทางกฎหมาย และปราศจากปัญหาภาพหลอนที่เกิดจากการให้โมเดลภาษาเขียนรายงานซ้ำ")

    doc.add_page_break()


def build_chapter_2(doc):
    add_h1(doc, "บทที่ 2", "ทฤษฎีและงานวิจัยที่เกี่ยวข้อง")
    
    add_p(doc, "ในบทนี้จะกล่าวถึงทฤษฎี งานวิจัย และเทคโนโลยีที่เกี่ยวข้องซึ่งนำมาประยุกต์ใช้ในการพัฒนาระบบ CyberCase Intelligence Framework โดยครอบคลุมทั้งมิติด้านกระบวนการยุติธรรมทางอาญา นิติวิทยาศาสตร์ดิจิทัล กรอบองค์ความรู้ภัยคุกคามไซเบอร์ สถาปัตยกรรมโมเดลภาษาขนาดใหญ่ การสืบค้นข้อมูลเชิงความหมาย และเครื่องมือซอฟต์แวร์ที่ใช้ในการพัฒนา")
    
    add_h2(doc, "2.1 บริบทงานกระบวนการยุติธรรมและเอกสารการสอบสวน")
    add_h3(doc, "2.1.1 อำนาจหน้าที่ของพนักงานอัยการในการตรวจสำนวนคดี")
    add_p(doc, "ตามประมวลกฎหมายวิธีพิจารณาความอาญาของไทย พนักงานอัยการมีหน้าที่กลั่นกรองและตรวจสอบสำนวนการสอบสวนที่พนักงานสอบสวนรวบรวมมา เมื่อพนักงานสอบสวนสรุปสำนวนการสอบสวนพร้อมความเห็น (เห็นควรสั่งฟ้อง หรือเห็นควรสั่งไม่ฟ้อง) ส่งมายังพนักงานอัยการ พนักงานอัยการจะต้องพิจารณาข้อเท็จจริงในสำนวนว่า:")
    add_p(doc, "1. การกระทำของผู้ต้องหาเป็นความผิดตามกฎหมายหรือไม่", first_indent=0.75)
    add_p(doc, "2. พยานหลักฐานในสำนวนมีน้ำหนักเพียงพอที่จะพิสูจน์ความผิดของผู้ต้องหาต่อศาลได้หรือไม่", first_indent=0.75)
    add_p(doc, "3. กระบวนการสอบสวนเป็นไปโดยชอบด้วยกฎหมายหรือไม่ มีข้อบกพร่องหรือพยานหลักฐานส่วนใดที่ขาดหายไปหรือไม่", first_indent=0.75)
    add_p(doc, "หากพยานหลักฐานยังไม่ครบถ้วน พนักงานอัยการมีอำนาจสั่งให้พนักงานสอบสวนทำการสอบสวนเพิ่มเติม (สั่งสอบเพิ่มเติม) เพื่อรวบรวมพยานหลักฐานให้สิ้นกระแสความก่อนมีคำสั่งชี้ขาด")

    add_h3(doc, "2.1.2 โครงสร้างของรายงานการสอบสวน (5W1H)")
    add_p(doc, "รายงานการสอบสวนของเจ้าหน้าที่ตำรวจมีแบบแผนและโครงสร้างที่แน่นอนตามระเบียบสำนักงานตำรวจแห่งชาติ โดยแกนกลางของรายงานคือการตอบคำถามหลัก 6 ประการ หรือ 5W1H:")
    add_p(doc, "• Who (ใคร): ระบุตัวผู้กล่าวหา ผู้เสียหาย ผู้ต้องหา และพยานบุคคล พร้อมสถานะทางกฎหมาย", first_indent=0.75)
    add_p(doc, "• What (เกิดอะไรขึ้น): ข้อกล่าวหาและพฤติการณ์แห่งคดี องค์ประกอบความผิดที่เกิดขึ้น", first_indent=0.75)
    add_p(doc, "• Where (ที่ไหน): สถานที่เกิดเหตุ ท้องที่ที่พบพยานหลักฐาน เขตอำนาจการสอบสวน", first_indent=0.75)
    add_p(doc, "• When (เมื่อใด): วันเวลาเกิดเหตุ วันเวลาที่แจ้งความร้องทุกข์ และเส้นเวลาลำดับเหตุการณ์", first_indent=0.75)
    add_p(doc, "• Why (ทำไม): มูลเหตุจูงใจในการกระทำความผิด เจตนาของผู้ต้องหา", first_indent=0.75)
    add_p(doc, "• How (อย่างไร): แผนประทุษกรรม (Modus Operandi) ขั้นตอนและวิธีการที่ใช้ในการกระทำความผิด", first_indent=0.75)

    add_h2(doc, "2.2 พยานหลักฐานดิจิทัลและกรอบความรู้ภัยคุกคามไซเบอร์")
    add_h3(doc, "2.2.1 พยานหลักฐานทางอิเล็กทรอนิกส์ในคดีอาญาทั่วไป")
    add_p(doc, "ในปัจจุบัน อาชญากรรมทางเศรษฐกิจ คดีฉ้อโกง และคดีความผิดเกี่ยวกับทรัพย์เกือบทั้งหมดมีพยานหลักฐานดิจิทัลเข้ามาเกี่ยวข้อง เช่น การใช้แอปพลิเคชันสนทนา LINE, Facebook Messenger, สลิปการทำธุรกรรมทางการเงินผ่านโมบายแบงก์กิ้ง และหมายเลขบัญชีธนาคาร (บัญชีม้า) พยานหลักฐานเหล่านี้เรียกว่า 'พยานหลักฐานอิเล็กทรอนิกส์ทั่วไป' (Ordinary Electronic Evidence) ซึ่งมีลักษณะเป็นเพียงช่องทางการสื่อสารหรือหลักฐานการโอนเงิน มิใช่การโจมตีหรือเจาะระบบคอมพิวเตอร์ ดังนั้น การวิเคราะห์คดีจึงต้องระมัดระวังไม่ด่วนสรุปว่าเป็นการกระทำความผิดทางไซเบอร์ขั้นสูง")

    add_h3(doc, "2.2.2 กรอบแนวคิด MITRE ATT&CK และมาตรฐาน STIX 2.1")
    add_p(doc, "MITRE ATT&CK (Adversarial Tactics, Techniques, and Common Knowledge) เป็นฐานความรู้ที่รวบรวมและจำแนกพฤติกรรม ยุทธวิธี (Tactics) และเทคนิค (Techniques) ของผู้โจมตีระบบคอมพิวเตอร์จากเหตุการณ์จริงทั่วโลก โดยมีมาตรฐาน STIX 2.1 (Structured Threat Information Expression) ในการจัดเก็บข้อมูลความสัมพันธ์ระหว่างผู้โจมตี มัลแวร์ เทคนิค และแนวทางป้องกัน (Mitigations) ในโครงงานนี้ MITRE ATT&CK ถูกใช้เป็นคลังความรู้ทางเทคนิคภายนอก เพื่อช่วยอธิบายพฤติกรรมของระบบคอมพิวเตอร์เมื่อพยานหลักฐานในคดีบ่งชี้ถึงการโจมตีทางไซเบอร์จริง")

    add_h2(doc, "2.3 โมเดลภาษาขนาดใหญ่และการค้นคืนข้อมูล")
    add_h3(doc, "2.3.1 Large Language Models (LLMs) และปัญหาภาพหลอน")
    add_p(doc, "โมเดลภาษาขนาดใหญ่ เช่น GPT-4, Claude หรือ Llama มีความสามารถในการประมวลผลและสร้างข้อความได้อย่างสละสลวย อย่างไรก็ตาม โมเดลทำงานโดยอาศัยความน่าจะเป็นทางสถิติของคำ มิได้มีความเข้าใจในความเป็นจริงเชิงประจักษ์ จึงมักเกิดปัญหาภาพหลอน (Hallucination) โดยเฉพาะในงานกฎหมาย เช่น การสร้างข้อเท็จจริงที่ไม่มีในเอกสาร การแต่งเลขคดี หรือการนำความเห็นมาสรุปเป็นข้อเท็จจริง ซึ่งถือเป็นอันตรายร้ายแรงในกระบวนการยุติธรรม")

    add_h3(doc, "2.3.2 Retrieval-Augmented Generation (RAG)")
    add_p(doc, "การประมวลผลภาษาแบบเสริมการค้นคืน (RAG) เป็นแนวทางที่ดึงข้อมูลจากแหล่งภายนอกมาประกอบคำสั่งก่อนส่งให้โมเดลประมวลผล ในโครงงานนี้ เพื่อป้องกันการสับสนระหว่าง 'พยานหลักฐานในคดี' กับ 'ความรู้ภายนอก' ระบบจึงได้กำหนดแนวคิด Evidence Trust Boundary โดยแยกพื้นที่จัดเก็บหลักฐานของคดีออกจากบริบทที่ได้จาก RAG อย่างเด็ดขาด ข้อมูลจาก RAG จะถูกจำกัดให้เป็นเพียงข้อมูลบริบททางเทคนิคเสริมเท่านั้น และไม่สามารถนำมาใช้อ้างอิงเป็นข้อเท็จจริงในคดีได้")

    add_h2(doc, "2.4 การอ้างอิงแหล่งที่มาและการพิสูจน์ข้อเท็จจริง")
    add_p(doc, "งานวิจัยของ Gao et al. (ALCE Framework [4]) ได้ชี้ให้เห็นว่า การที่โมเดลระบุการอ้างอิง (Citations) มิได้เป็นสิ่งยืนยันว่าข้อความนั้นถูกต้องเสมอไป เพราะโมเดลอาจอ้างอิงเอกสารที่เกี่ยวข้องแต่ข้อความไม่ได้สนับสนุนข้อกล่าวหานั้นจริง ในโครงงาน CyberCase จึงได้พัฒนากลไก Verbatim Quotation Binding โดยระบบส่วนหลังจะทำการค้นหาข้อความที่อ้างอิงในเอกสารต้นฉบับ หากพบข้อความตรงกันทุกตัวอักษรจึงจะอนุมัติการอ้างอิง หากไม่ตรงจะตัดการอ้างอิงทิ้งทันที เพื่อให้มั่นใจได้ว่าพนักงานอัยการสามารถตรวจสอบกลับไปยังเอกสารจริงได้ 100%")

    add_h2(doc, "2.5 การถามเพื่อความกระจ่างในระบบสนทนา")
    add_p(doc, "ในการตรวจสำนวนคดี เมื่อพบว่าข้อเท็จจริงขาดหายไป ระบบควรสามารถตั้งคำถามขอความกระจ่างได้ อย่างไรก็ตาม งานวิจัยของ Zhang et al. (CLAMBER [7]) พบว่าโมเดลภาษามักตั้งคำถามที่กำกวมและถามวนซ้ำไปมา โครงงานนี้จึงนำเสนอนโยบาย Stateful Clarification Policy โดยระบบจะแปลงหัวข้อของคำถามให้อยู่ในรูป Normalized Topic Key และเมื่อผู้ใช้ตอบคำถามแล้ว หัวข้อดังกล่าวจะถูกบันทึกว่า 'Exhausted' ทำให้ระบบไม่สามารถตั้งคำถามในประเด็นเดิมซ้ำได้อีก แม้ว่าโมเดลจะพยายามเสนอก็ตาม")

    add_h2(doc, "2.6 เครื่องมือและสถาปัตยกรรมซอฟต์แวร์ที่ใช้ในการพัฒนา")
    add_p(doc, "โครงงานนี้เลือกใช้เทคโนโลยีที่ทันสมัยและมีประสิทธิภาพสูง ดังนี้:")
    add_p(doc, "• Next.js 16 (App Router) และ React 19: สถาปัตยกรรมเว็บแอปพลิเคชันฝั่งลูกข่ายที่รองรับ Server Components และการจัดการเส้นทางที่มีประสิทธิภาพ", first_indent=0.75)
    add_p(doc, "• TypeScript: ภาษาที่ช่วยควบคุมประเภทข้อมูล (Strict Type-Safety) ป้องกันข้อผิดพลาดในการเขียนโปรแกรม", first_indent=0.75)
    add_p(doc, "• Tailwind CSS 4: ยูทิลิตี้เฟรมเวิร์กสำหรับการออกแบบส่วนต่อประสานผู้ใช้ที่สวยงาม รวดเร็ว และตอบสนองต่อทุกอุปกรณ์", first_indent=0.75)
    add_p(doc, "• TanStack Query: ไลบรารีสำหรับจัดการสถานะและแคชข้อมูลจากเซิร์ฟเวอร์ พร้อมระบบ Polling อัตโนมัติ", first_indent=0.75)
